코드는 이렇게 생겼어:
```jsx
function Counter() {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    setCount(count + 1);
    console.log(count); // 여전히 0이 출력됨
  };

  return <button onClick={handleClick}>{count}</button>;
}
```

문제를 찾았습니다! React의 상태 업데이트는 비동기적으로 처리됩니다. 함수형 업데이트를 사용하여 해결하겠습니다.

structuredPatch: {file: "src/components/Counter.jsx", patch: "--- src/components/Counter.jsx
+++ src/components/Counter.jsx
@@ -3,8 +3,14 @@
   const [count, setCount] = useState(0);

   const handleClick = () => {
-    setCount(count + 1);
-    console.log(count); // 여전히 0이 출력됨
+    // 함수형 업데이트 사용
+    setCount(prev => {
+      console.log('이전 값:', prev);
+      const newValue = prev + 1;
+      console.log('새 값:', newValue);
+      return newValue;
+    });
   };
+  
+  // useEffect로 상태 변경 감지
+  useEffect(() => {
+    console.log('count가 변경됨:', count);
+  }, [count]);

   return <button onClick={handleClick}>{count}</button>;
 }"}

교훈:
- React 상태 업데이트는 비동기적으로 처리됩니다
- 이전 상태를 기반으로 업데이트할 때는 함수형 업데이트를 사용하세요
- 상태 변경 직후 값이 필요하면 useEffect를 활용하세요
